<script lang="ts">
	import { onMount } from 'svelte';

	let className = '';

	export let onStateChange = (stateCode: string) => {};
	export { className as class };

	let mapSvg: SVGSVGElement | null = null;

	onMount(() => {
		mapSvg?.querySelectorAll('path').forEach((path) => {
			path.addEventListener('click', () => {
				const code = path.getAttribute('id')?.toString() || 'DL';
				onStateChange(code);

				// remove all fill colors from other state
				mapSvg?.querySelectorAll('path').forEach((path) => {
					path.style.fill = '#D3F2FC';
					path.style.stroke = '#A1A6B5';
				});

				path.style.fill = '#0d2561';
				path.style.stroke = '#0d2561';
			});
		});
	});
</script>

